mapper.update:
update p_generation_attempt set lease_epoch = #{leaseEpoch}, updated_at = utc_timestamp(3)
where id = #{attemptId} and step_id = #{stepId} and request_hash = #{requestHash}
  and lease_epoch <= #{leaseEpoch} and status in ('PREPARED', 'SUBMITTED')

update p_generation_attempt set status = #{status}, completed_at = coalesce(completed_at, utc_timestamp(3)), updated_at = utc_timestamp(3)
where id = #{attemptId} and step_id = #{stepId} and attempt_no = #{attemptNo} and lease_epoch = #{leaseEpoch}
  and status = #{status}

update p_generation_task set status = 'FAILED', internal_state = 'FINISHED',
    error_code = (select s.error_code from p_generation_step s where s.account_id = #{accountId}
        and s.task_id = #{taskId} and s.status in ('FAILED','UNKNOWN') order by s.updated_at desc limit 1),
    finished_at = utc_timestamp(3), updated_at = utc_timestamp(3)
where account_id = #{accountId} and id = #{taskId} and status in ('QUEUED', 'PROCESSING')
  and not exists (select 1 from p_generation_step active_step where active_step.task_id = #{taskId}
      and active_step.step_type = 'GENERATE_ACTION' and active_step.status in ('READY','RUNNING','POLLING'))
  and exists (select 1 from p_generation_step failed_step where failed_step.task_id = #{taskId}
      and failed_step.status in ('FAILED','UNKNOWN'))
